 const auto funded=take(x.movement_actions.read_original_execution_funding_plan(action));if(!funded||funded->source_schema!=1||!same(funded->source_ref,SourceRef{"tasks","task_carrier_agreement_accepted",a.id}))reject("TaskReportAcceptedFundingExecutionRequired",a.id);
