 const auto*named=std::get_if<StableId>(&destination.destination);const auto*place=x.common_catalog.places.find(a.terms.destination_site_id);
 if(!place||!named||*named!=place->settlement_id||destination.action_id!=action||destination.actor_id!=r.terms.carrier_actor_id||destination.execution_source.source_schema!=proof.source_schema||!same(destination.execution_source.source_ref,proof.original_execution_source))reject("TaskReportAcceptedDestinationMismatch",a.id);
